nltk.download("vader_lexicon")

sia = SentimentIntensityAnalyzer()


@F.udf(DoubleType())
def vader_compound(text):
    if text is None or text.strip() == "":
        return 0.0

    return float(
        sia.polarity_scores(text)["compound"]
    )


